// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./GaleonBrain.sol";

/**
 * @title GaleonRouter
 * @notice AI Micro-Execution Router for Monad
 * @dev Collects 0.5% fee, executes swaps via Kuru (or any DEX),
 *      records AI-Endorsed Trades, manages Micro-Execution positions.
 *
 * Swap execution: Backend calls Kuru Flow API to get swap calldata,
 * then passes it to this contract. Contract handles fee + AI endorsement.
 */

interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract GaleonRouter {
    address public owner;
    GaleonBrain public galeonBrain;
    address public feeReceiver;
    uint256 public feeRate = 50; // 0.5% = 50 / 10000

    // Approved DEX targets (Kuru Router, Kuru Flow, etc.)
    mapping(address => bool) public approvedTargets;

    // ========== Micro-Execution Position ==========
    struct MicroPosition {
        address trader;
        address tokenIn;
        address tokenOut;
        uint256 totalAmountIn;
        uint256 totalTokenAmount;
        uint256 realizedPnl;
        uint8 stepCount;
        uint256 decisionId;
        uint256 endorsedTradeId;
        bool isOpen;
        uint256 openedAt;
    }

    mapping(uint256 => MicroPosition) public microPositions;
    uint256 public positionCount;
    mapping(address => uint256[]) public traderPositions;

    // ========== Events ==========
    event MicroPositionOpened(uint256 indexed positionId, address indexed trader, address token, uint256 amount, uint256 decisionId);
    event MicroStep(uint256 indexed positionId, string stepType, uint256 amountIn, uint256 amountOut, uint8 stepNumber);
    event MicroPositionClosed(uint256 indexed positionId, uint256 totalIn, uint256 totalOut, int256 pnlBps);
    event FeeCollected(address indexed trader, uint256 feeAmount);
    event SwapExecuted(address indexed trader, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);

    constructor(address _galeonBrain, address _feeReceiver) {
        owner = msg.sender;
        galeonBrain = GaleonBrain(_galeonBrain);
        feeReceiver = _feeReceiver;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    // ========== Admin ==========
    function setApprovedTarget(address target, bool approved) external onlyOwner {
        approvedTargets[target] = approved;
    }

    function setFeeRate(uint256 _feeRate) external onlyOwner {
        require(_feeRate <= 100, "Fee too high");
        feeRate = _feeRate;
    }

    function setFeeReceiver(address _feeReceiver) external onlyOwner {
        feeReceiver = _feeReceiver;
    }

    // ========== Fee ==========
    function _collectFee(address token, uint256 amount) internal returns (uint256 afterFee) {
        uint256 fee = (amount * feeRate) / 10000;
        afterFee = amount - fee;
        if (fee > 0) {
            IERC20(token).transfer(feeReceiver, fee);
            emit FeeCollected(msg.sender, fee);
        }
    }

    // ========== Core: Execute swap via pre-built calldata ==========
    /**
     * @notice Execute a swap through an approved DEX target
     * @param target DEX router address (must be approved)
     * @param tokenIn Token being sold
     * @param tokenOut Token being bought
     * @param amountIn Amount of tokenIn
     * @param swapCalldata Pre-built calldata from Kuru Flow API
     * @param decisionId Brain decision ID for AI endorsement
     */
    function executeSwap(
        address target,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        bytes calldata swapCalldata,
        uint256 decisionId
    ) external returns (uint256 amountOut) {
        require(approvedTargets[target], "Target not approved");

        // Transfer tokenIn from user
        IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        // Collect fee
        uint256 swapAmount = _collectFee(tokenIn, amountIn);

        // Approve target and execute swap
        IERC20(tokenIn).approve(target, swapAmount);
        uint256 balBefore = IERC20(tokenOut).balanceOf(address(this));

        (bool success,) = target.call(swapCalldata);
        require(success, "Swap failed");

        amountOut = IERC20(tokenOut).balanceOf(address(this)) - balBefore;

        // Transfer output to user
        IERC20(tokenOut).transfer(msg.sender, amountOut);

        // Record AI endorsement
        galeonBrain.recordEndorsedTrade(msg.sender, tokenOut, amountIn, decisionId);

        emit SwapExecuted(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ========== Micro-Execution: Open Position (DCA Step 1) ==========
    function openMicroPosition(
        address target,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        bytes calldata swapCalldata,
        uint256 decisionId
    ) external returns (uint256 positionId) {
        require(approvedTargets[target], "Target not approved");

        IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 swapAmount = _collectFee(tokenIn, amountIn);

        IERC20(tokenIn).approve(target, swapAmount);
        uint256 balBefore = IERC20(tokenOut).balanceOf(address(this));
        (bool success,) = target.call(swapCalldata);
        require(success, "Swap failed");
        uint256 amountOut = IERC20(tokenOut).balanceOf(address(this)) - balBefore;

        // Keep tokens in contract (held for position)
        uint256 endorsedTradeId = galeonBrain.recordEndorsedTrade(msg.sender, tokenOut, amountIn, decisionId);

        positionId = positionCount++;
        microPositions[positionId] = MicroPosition({
            trader: msg.sender,
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            totalAmountIn: amountIn,
            totalTokenAmount: amountOut,
            realizedPnl: 0,
            stepCount: 1,
            decisionId: decisionId,
            endorsedTradeId: endorsedTradeId,
            isOpen: true,
            openedAt: block.timestamp
        });

        traderPositions[msg.sender].push(positionId);

        emit MicroPositionOpened(positionId, msg.sender, tokenOut, amountIn, decisionId);
        emit MicroStep(positionId, "DCA_IN", amountIn, amountOut, 1);
    }

    // ========== Micro-Execution: DCA Add ==========
    function addToPosition(
        uint256 positionId,
        address target,
        uint256 amountIn,
        bytes calldata swapCalldata
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Closed");
        require(pos.trader == msg.sender, "Not yours");
        require(approvedTargets[target], "Target not approved");

        IERC20(pos.tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 swapAmount = _collectFee(pos.tokenIn, amountIn);

        IERC20(pos.tokenIn).approve(target, swapAmount);
        uint256 balBefore = IERC20(pos.tokenOut).balanceOf(address(this));
        (bool success,) = target.call(swapCalldata);
        require(success, "Swap failed");
        uint256 amountOut = IERC20(pos.tokenOut).balanceOf(address(this)) - balBefore;

        pos.totalAmountIn += amountIn;
        pos.totalTokenAmount += amountOut;
        pos.stepCount++;
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);

        emit MicroStep(positionId, "DCA_IN", amountIn, amountOut, pos.stepCount);
    }

    // ========== Micro-Execution: Partial Exit ==========
    function partialExit(
        uint256 positionId,
        address target,
        uint256 tokenAmount,
        bytes calldata swapCalldata
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Closed");
        require(pos.trader == msg.sender, "Not yours");
        require(tokenAmount <= pos.totalTokenAmount, "Exceeds");
        require(approvedTargets[target], "Target not approved");

        IERC20(pos.tokenOut).approve(target, tokenAmount);
        uint256 balBefore = IERC20(pos.tokenIn).balanceOf(address(this));
        (bool success,) = target.call(swapCalldata);
        require(success, "Swap failed");
        uint256 amountOut = IERC20(pos.tokenIn).balanceOf(address(this)) - balBefore;

        uint256 afterFee = _collectFee(pos.tokenIn, amountOut);
        IERC20(pos.tokenIn).transfer(msg.sender, afterFee);

        pos.totalTokenAmount -= tokenAmount;
        pos.realizedPnl += afterFee;
        pos.stepCount++;
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);

        emit MicroStep(positionId, "PARTIAL_TP", tokenAmount, afterFee, pos.stepCount);
    }

    // ========== Micro-Execution: Close Position ==========
    function closePosition(
        uint256 positionId,
        address target,
        bytes calldata swapCalldata
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Closed");
        require(pos.trader == msg.sender, "Not yours");

        uint256 remainingTokens = pos.totalTokenAmount;
        uint256 exitProceeds = 0;

        if (remainingTokens > 0 && approvedTargets[target]) {
            IERC20(pos.tokenOut).approve(target, remainingTokens);
            uint256 balBefore = IERC20(pos.tokenIn).balanceOf(address(this));
            (bool success,) = target.call(swapCalldata);
            require(success, "Swap failed");
            uint256 amountOut = IERC20(pos.tokenIn).balanceOf(address(this)) - balBefore;
            exitProceeds = _collectFee(pos.tokenIn, amountOut);
            IERC20(pos.tokenIn).transfer(msg.sender, exitProceeds);
        }

        uint256 totalOut = pos.realizedPnl + exitProceeds;
        int256 pnlBps = 0;
        if (pos.totalAmountIn > 0) {
            pnlBps = int256((totalOut * 10000) / pos.totalAmountIn) - 10000;
        }

        pos.isOpen = false;
        pos.totalTokenAmount = 0;
        pos.stepCount++;
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);
        galeonBrain.settleTrade(pos.endorsedTradeId, pnlBps);

        emit MicroStep(positionId, "FULL_EXIT", remainingTokens, exitProceeds, pos.stepCount);
        emit MicroPositionClosed(positionId, pos.totalAmountIn, totalOut, pnlBps);
    }

    // ========== Emergency Exit (same as close, separate event type) ==========
    function emergencyExit(
        uint256 positionId,
        address target,
        bytes calldata swapCalldata
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Closed");
        require(pos.trader == msg.sender, "Not yours");

        uint256 remainingTokens = pos.totalTokenAmount;
        uint256 exitProceeds = 0;

        if (remainingTokens > 0 && approvedTargets[target]) {
            IERC20(pos.tokenOut).approve(target, remainingTokens);
            uint256 balBefore = IERC20(pos.tokenIn).balanceOf(address(this));
            (bool success,) = target.call(swapCalldata);
            require(success, "Swap failed");
            uint256 amountOut = IERC20(pos.tokenIn).balanceOf(address(this)) - balBefore;
            exitProceeds = _collectFee(pos.tokenIn, amountOut);
            IERC20(pos.tokenIn).transfer(msg.sender, exitProceeds);
        }

        uint256 totalOut = pos.realizedPnl + exitProceeds;
        int256 pnlBps = pos.totalAmountIn > 0
            ? int256((totalOut * 10000) / pos.totalAmountIn) - 10000
            : int256(0);

        pos.isOpen = false;
        pos.totalTokenAmount = 0;
        pos.stepCount++;
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);
        galeonBrain.settleTrade(pos.endorsedTradeId, pnlBps);

        emit MicroStep(positionId, "RISK_EXIT", remainingTokens, exitProceeds, pos.stepCount);
        emit MicroPositionClosed(positionId, pos.totalAmountIn, totalOut, pnlBps);
    }

    // ========== Query ==========
    function getTraderPositionCount(address trader) external view returns (uint256) {
        return traderPositions[trader].length;
    }

    function getTraderPositionId(address trader, uint256 index) external view returns (uint256) {
        return traderPositions[trader][index];
    }

    // ========== Rescue ==========
    function rescueTokens(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }

    receive() external payable {}
}

